"""End-to-end runs against the practice tasks."""

from __future__ import annotations

import tempfile
import unittest
from pathlib import Path

from eval.runner import load_tasks, run_suite
from src.config import PROJECT_ROOT
from src.orchestrator.runner import Platform

DEMO_GOAL = (
    "Write a Markdown report listing the first 15 Fibonacci numbers, "
    "generated by a Python script."
)


class FlowTests(unittest.TestCase):
    def test_practice_set_meets_criteria(self) -> None:
        root = Path(tempfile.mkdtemp())
        tasks = load_tasks(PROJECT_ROOT / "eval" / "tasks.example.json")
        _report, records = run_suite(root, tasks, offline=True, echo=False)
        self.assertEqual(len(records), 3)
        for record in records:
            self.assertFalse(record.fatal, record.transcript)
            self.assertTrue(record.success, record.transcript)
            self.assertTrue(record.criteria_met, record.criteria_notes)
            self.assertFalse(any("list index out of range" in line for line in record.transcript))
        self.assertTrue(any("Recorded 2 subtasks" in line for line in records[0].transcript))

    def test_second_run_recalls_memory(self) -> None:
        root = Path(tempfile.mkdtemp())
        platform = Platform(root=root, offline=True, echo=False)
        platform.run_group(DEMO_GOAL, task_id="first")
        second = platform.run_group(DEMO_GOAL, task_id="second")
        self.assertTrue(any("Recalled" in line for line in second.transcript))
        self.assertTrue((root / "data" / "memory" / "coder.json").is_file())


if __name__ == "__main__":
    unittest.main()
